import time
from pyflink.table import EnvironmentSettings, TableEnvironment

# Path to the CSV folder generated by the Python script
DATA_PATH = "file:///data/events_3parts" 
TOTAL_ROWS = 300000

def run_benchmark():
    print("Initializing Flink Environment in STREAMING mode...")
    
    # 1. SET TO STREAMING MODE (Pipelined Execution)
    # This ensures Flink operates as a true Stream Processing System
    env_settings = EnvironmentSettings.in_streaming_mode()
    t_env = TableEnvironment.create(env_settings)

    # 2. ENABLE LATENCY TRACKING
    # This allows Prometheus/Grafana to capture Latency metrics (Mean, Median, Max) 
    t_env.get_config().set("pipeline.latency-tracking.interval", "1000")

    # 3. DEFINE SOURCE TABLE (Events Stream)
    # Mapping the CSV files as a continuous stream of data
    t_env.execute_sql(f"""
        CREATE TABLE events_by_user (
            user_id BIGINT,
            event_id BIGINT,
            ts STRING,
            event_type STRING,
            amount DOUBLE
        ) WITH (
            'connector' = 'filesystem',
            'path' = '{DATA_PATH}',
            'format' = 'csv',
            'csv.ignore-parse-errors' = 'true'
        )
    """)

    # 4. DEFINE SINKS (Blackhole for performance profiling)
    # Blackhole connector avoids I/O bottlenecks to measure framework overhead
    t_env.execute_sql("""
        CREATE TABLE benchmark_sink (
            user_id BIGINT, event_id BIGINT, ts STRING, event_type STRING, amount DOUBLE
        ) WITH ('connector' = 'blackhole')
    """)
    
    t_env.execute_sql("""
        CREATE TABLE agg_sink (
            user_id BIGINT, n_events BIGINT
        ) WITH ('connector' = 'blackhole')
    """)

    # ==========================================
    # BENCHMARK EXECUTION
    # ==========================================

    # QUERY 1: Single User Filter (Selectivity Test)
    print("\nExecuting Query 1: SELECT * FROM events_by_user WHERE user_id = 12345")
    start_time = time.perf_counter()
    t_env.execute_sql("INSERT INTO benchmark_sink SELECT * FROM events_by_user WHERE user_id = 12345").wait()
    print_results("Query 1", start_time, time.perf_counter())

    # QUERY 2: Point Lookup (Primary Key Analogy)
    print("\nExecuting Query 2: SELECT * FROM events... WHERE user_id = 12345 AND event_id = 987")
    start_time = time.perf_counter()
    t_env.execute_sql("INSERT INTO benchmark_sink SELECT * FROM events_by_user WHERE user_id = 12345 AND event_id = 987").wait()
    print_results("Query 2", start_time, time.perf_counter())

    # QUERY 3: State-centric Aggregation (Group By)
    print("\nExecuting Query 3: SELECT user_id, COUNT(*) FROM events_by_user GROUP BY user_id")
    start_time = time.perf_counter()
    t_env.execute_sql("INSERT INTO agg_sink SELECT user_id, COUNT(*) AS n_events FROM events_by_user GROUP BY user_id").wait()
    print_results("Query 3", start_time, time.perf_counter())

def print_results(query_name, start, end):
    total_time = end - start
    op_rate = TOTAL_ROWS / total_time
    
    print(f"===== FLINK {query_name} BENCHMARK RESULTS =====")
    print(f"Processed Rows: {TOTAL_ROWS}")
    print(f"Throughput (Op rate): {op_rate:.2f} rows/s")
    print(f"Total Execution Time: {total_time:.3f} s")
    print("Action Required: Collect Latency (Mean, Median, Max) and GC Time from Grafana Dashboard.")

if __name__ == '__main__':
    run_benchmark()